#!/usr/bin/env bash
# tests/infra/test_host_global_unit_pinning.sh
#
# Guards that HOST-GLOBAL systemd --user units generated by scripts/setup-dev.sh
# and scripts/setup-agent-cache-redirect.sh name a STABLE main-checkout path in
# their ExecStart, never the (possibly ephemeral) checkout that happened to
# invoke the installer.
#
# Background (task 5888): setup-dev.sh's install_build_services() writes four
# units into the host-global $HOME/.config/systemd/user.  Until the fix that
# lands WITH this suite, the two jobserver units derived their ExecStart from
# ${BASH_SOURCE[0]} — the INVOKING checkout.  Run once from a warm lane
# (/home/leo/src/warm-lanes/worktrees/_lane-N), those two units were pinned at
# a path that vanishes the moment that lane is reclaimed and re-seeded.  From
# then on every start fails with status=203/EXEC, the dual-pool cargo jobserver
# never comes up, and every verify silently fails-open to a private -j(nproc) —
# completely silently, because nothing Requires= those units.  The fix sources
# scripts/lib_main_checkout.sh from install_build_services() and interpolates
# the resolved main checkout into both ExecStarts (and the chmod that makes
# exactly those two executables runnable), leaving every per-worktree call site
# alone — which is what B5b/B5c pin.  Same defect class, same fix shape, as the
# prior art in scripts/setup-agent-cache-redirect.sh's install_boot_unit()
# (cited by FUNCTION rather than line range, so the reference cannot rot; that
# site was itself migrated onto this same resolver by task 6864 — Part C), and
# the same host convention already encoded on
# deploy/systemd/reify-warm-lane{,-gc}.service
# (#4720): a host-global unit names the stable main checkout.
#
# Part A — the RESOLVER contract (scripts/lib_main_checkout.sh).
# Part B — the GENERATOR contract (see the section banner further down).
# Part C — the BOOT-UNIT generator contract: the SECOND host-global generator,
#          scripts/setup-agent-cache-redirect.sh's install_boot_unit() (task
#          6864; see the section banner further down).
#
# WHY PART A EXISTS SEPARATELY: `git rev-parse --git-common-dir` is RELATIVE
# inside the main checkout (`.git`, or `../../.git` from a subdir) and absolute
# only inside a linked worktree, so the obvious `dirname "$(git rev-parse
# --git-common-dir)"` yields `.` exactly where it must not.  These cases pin
# `--path-format=absolute` and the `git -C` anchoring that make it uniform.
#
# HERMETIC (`pool` bucket in run-all-classification.manifest): every fixture is
# a mktemp -d git repo.  Nothing here reads or writes the real
# ~/.config/systemd/user, runs systemctl, or touches a host FIFO.
#
# Auto-discovered by tests/infra/run_all.sh via the test_*.sh glob.

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "$SCRIPT_DIR/../.." && pwd)"
LIB_MAIN_CHECKOUT="$REPO_ROOT/scripts/lib_main_checkout.sh"

[ -f "$SCRIPT_DIR/test_helpers.sh" ] || {
    echo "ERROR: test_helpers.sh not found at $SCRIPT_DIR/test_helpers.sh" >&2
    exit 1
}
# shellcheck source=tests/infra/test_helpers.sh
source "$SCRIPT_DIR/test_helpers.sh"

_TMPDIRS=()
cleanup() {
    local d
    for d in "${_TMPDIRS[@]:-}"; do
        [ -n "$d" ] && rm -rf "$d"
    done
    # MANDATORY. This runs from the EXIT trap, so its return value BECOMES the
    # suite's exit status: with an empty _TMPDIRS the loop's last command is a
    # false `[ -n "" ]`, and the suite would exit 1 with every assertion green.
    return 0
}
trap cleanup EXIT

echo "=== host-global systemd unit ExecStart pinning ==="

# ---------------------------------------------------------------------------
# _fixture_git <git args...> — git for FIXTURE CONSTRUCTION ONLY, with the
# ambient repository environment stripped.
#
# reify runs its whole verify gate from hooks/pre-merge-commit, and git EXPORTS
# GIT_DIR (and friends) into every hook.  An inherited GIT_DIR outranks `git -C`
# — measured — so the `git init` / `worktree add` calls below would operate on
# the REAL repository instead of the mktemp fixture.  Same precedent as
# tests/infra/test_spec_anchor_lint.sh:1182.
#
# The asymmetry with _resolver_out below is DELIBERATE: fixture construction
# sanitizes, the code under test does not get sanitized FOR it.  The resolver
# has to survive a hostile ambient environment on its own — that is what A6
# asserts, and a harness that pre-cleaned the environment would be certifying a
# posture production never actually has.
# ---------------------------------------------------------------------------
_fixture_git() {
    env -u GIT_DIR -u GIT_WORK_TREE -u GIT_COMMON_DIR -u GIT_INDEX_FILE git "$@"
}

# ---------------------------------------------------------------------------
# SHARED GENERATOR-FIXTURE SCAFFOLDING (Parts B and C).
#
# The two generator fixtures below are NOT merged into one: they commit
# different executables, strip different exec bits, and extract a different
# function out of a different script, and their mode sets do not overlap.  What
# IS identical is the mechanical scaffolding — the mktemp root, the recording
# systemctl shim, the initial commit — and those live here rather than being
# written twice, so a fix to any of them (a new variable in _fixture_git's strip
# set, a shim that records exit codes) cannot land for one Part's harness and
# silently leave the other on the old posture.
# ---------------------------------------------------------------------------

# _mk_fixture_root <stem> — MAIN-SHELL ONLY, and transitively so is every caller.
# Mints a canonicalized mktemp root, registers it in _TMPDIRS for the EXIT trap,
# and sets _FIXTURE_ROOT.  It sets a global rather than echoing because an
# append performed inside a command-substitution SUBSHELL is silently discarded,
# leaking the whole fixture tree — see _mk_two_checkout_fixture's banner.
#
# `pwd -P` canonicalizes so fixture paths compare byte-for-byte against git's
# own absolute output (macOS /tmp -> /private/tmp, and any symlinked TMPDIR).
_FIXTURE_ROOT=""
_mk_fixture_root() {
    local stem="$1" root
    root="$(mktemp -d "${TMPDIR:-/tmp}/${stem}-XXXXXX")" || return 1
    root="$(cd "$root" && pwd -P)" || return 1
    _TMPDIRS+=("$root")
    _FIXTURE_ROOT="$root"
}

# _write_systemctl_shim <bindir> <logfile> — a `systemctl` placed earlier on PATH
# than the real one, RECORDING its argv to <logfile> and exiting 0.  Neither
# generator's daemon-reload / `enable --now` may reach the host.
#
# Recording rather than merely no-op is load-bearing: both generators write
# their unit files well before their reload/enable tail, so unit PRESENCE cannot
# distinguish "installed" from "aborted two lines later".  Only the log can, and
# B9c and C4 depend on exactly that distinction.
_write_systemctl_shim() {
    local bindir="$1" log="$2"
    mkdir -p "$bindir" || return 1
    printf '#!/usr/bin/env bash\nprintf "%%s\\n" "$*" >> %s\nexit 0\n' "$log" \
        > "$bindir/systemctl" || return 1
    chmod +x "$bindir/systemctl" || return 1
}

# _fixture_init_commit <dir> — `git init -b main` + `add -A` + an initial commit
# that is independent of the developer's identity and signing config.  Routed
# through _fixture_git so an ambient GIT_DIR cannot redirect it at the REAL
# repository (see that function's banner).
#
# Committing before the caller's `git worktree add` is what makes a linked lane
# check out its own separate, mode-755 inodes — the asymmetry every noexec mode
# below depends on.
_fixture_init_commit() {
    local dir="$1"
    _fixture_git init -q -b main "$dir" || return 1
    _fixture_git -C "$dir" add -A || return 1
    _fixture_git -C "$dir" -c user.name=t -c user.email=t@example.invalid \
        -c commit.gpgsign=false commit -q -m init || return 1
}

# ---------------------------------------------------------------------------
# _mk_two_checkout_fixture <stem> — MAIN-SHELL ONLY. Mints a temp MAIN checkout
# with a REAL linked worktree beside it, and sets FIX_ROOT / FIX_MAIN /
# FIX_LANE.
#
# MUST NOT be called from a command substitution. It registers its mktemp root
# in _TMPDIRS for the EXIT trap, and an append performed inside a
# command-substitution SUBSHELL is silently discarded when that subshell exits
# — leaking the whole fixture tree (git repo + linked worktree) on every run.
# That is why this sets globals instead of echoing them, the same subshell trap
# test_helpers.sh's make_isolated_lane documents.
#
# A real `git worktree add` (not a simulated directory layout) is what makes
# this reproduce the bug rather than model it: the linked worktree is the only
# thing that makes --git-common-dir point somewhere other than the CWD's .git.
#
# Paths are canonicalized with `pwd -P` so they compare byte-for-byte against
# git's own absolute output.
# ---------------------------------------------------------------------------
_mk_two_checkout_fixture() {
    local stem="$1" root
    root="$(mktemp -d "${TMPDIR:-/tmp}/${stem}-XXXXXX")" || return 1
    root="$(cd "$root" && pwd -P)" || return 1
    _TMPDIRS+=("$root")
    FIX_ROOT="$root"
    FIX_MAIN="$root/main"
    FIX_LANE="$root/lane"
    # A third, entirely UNRELATED repository. Only used as the poison target for
    # A6: it is what an un-neutralized resolver answers when GIT_DIR (or
    # GIT_COMMON_DIR) is exported into the environment, which is what makes that
    # section non-vacuous.
    FIX_OTHER="$root/other"
    mkdir -p "$FIX_MAIN/sub/deep" || return 1
    _fixture_git init -q -b main "$FIX_MAIN" || return 1
    _fixture_git -C "$FIX_MAIN" -c user.name=t -c user.email=t@example.invalid \
        -c commit.gpgsign=false commit -q --allow-empty -m init || return 1
    _fixture_git -C "$FIX_MAIN" worktree add -q --detach "$FIX_LANE" >/dev/null 2>&1 || return 1
    mkdir -p "$FIX_LANE/sub/deep" || return 1
    _fixture_git init -q -b main "$FIX_OTHER" || return 1
    _fixture_git -C "$FIX_OTHER" -c user.name=t -c user.email=t@example.invalid \
        -c commit.gpgsign=false commit -q --allow-empty -m init || return 1
    return 0
}

# ---------------------------------------------------------------------------
# _resolver_out <cwd> <anchor> [ENV=VAL ...] — stdout of
# `reify_main_checkout <anchor>` run in a FRESH bash, from <cwd>.
#
# A fresh bash per case (rather than sourcing once into this shell) is what
# makes the ambient-CWD and REIFY_MAIN_CHECKOUT cases genuinely independent:
# bash's rules for a `VAR=v func` prefix on a *function* are subtle, and a
# leaked CWD or a leaked override would silently make a later case vacuous.
#
# ONLY REIFY_MAIN_CHECKOUT is scrubbed here — it is the override UNDER TEST, so
# an ambient one would make A2/A5 pass without the git derivation running at
# all.  The git repository environment (GIT_DIR, GIT_WORK_TREE, GIT_COMMON_DIR,
# GIT_INDEX_FILE) is deliberately NOT scrubbed: those are exactly the variables
# that outrank `git -C`, the resolver is responsible for neutralizing them
# itself, and a harness that pre-cleaned them would leave that responsibility
# permanently untested.  A6 poisons them on purpose.
#
# A FAILED call reads back as the EMPTY string at every call site below, never
# as a placeholder: a non-empty sentinel would satisfy the `-n` guards in the
# negative assertions (A2e, A5a) and let them pass vacuously against a resolver
# that does not exist at all.
# ---------------------------------------------------------------------------
_resolver_out() {
    local cwd="$1" anchor="$2"
    shift 2
    (
        cd "$cwd" || exit 1
        env -u REIFY_MAIN_CHECKOUT "$@" \
            bash -c 'source "$1" || exit 1; reify_main_checkout "$2"' _ \
            "$LIB_MAIN_CHECKOUT" "$anchor"
    )
}

# =============================================================================
# PART A — the main-checkout RESOLVER contract
# =============================================================================
echo ""
echo "--- A0: scripts/lib_main_checkout.sh exists and is sourceable ---"

assert "scripts/lib_main_checkout.sh exists" \
    test -f "$LIB_MAIN_CHECKOUT"

assert "scripts/lib_main_checkout.sh parses (bash -n)" \
    bash -n "$LIB_MAIN_CHECKOUT"

assert "sourcing scripts/lib_main_checkout.sh defines reify_main_checkout" \
    bash -c 'source "$1" || exit 1; declare -F reify_main_checkout >/dev/null' _ "$LIB_MAIN_CHECKOUT"

echo ""
echo "--- A1: two-checkout fixture (real linked worktree) ---"

FIX_ROOT=""; FIX_MAIN=""; FIX_LANE=""; FIX_OTHER=""
_mk_two_checkout_fixture reify-mainck   # main shell, NOT $( ) — see the header
FIX_NOREPO="$FIX_ROOT/outside"
mkdir -p "$FIX_NOREPO"

# The fixture's own registration is what the EXIT trap reclaims; assert it
# happened rather than trusting it, so a future refactor that reintroduces the
# command-substitution form fails here instead of leaking a git repo per run.
assert "fixture: the mktemp root is registered in _TMPDIRS for the EXIT trap" \
    bash -c '[ "$1" = "$2" ] && [ -n "$2" ]' _ "${_TMPDIRS[0]:-}" "$FIX_ROOT"

# NON-VACUITY CONTROL, asserted BEFORE any resolver case: if these two paths
# were equal, every "resolves to the main checkout, not the lane" assertion
# below would pass no matter what the resolver did.
assert "fixture: the main checkout and the linked worktree are DISTINCT paths" \
    bash -c '[ "$1" != "$2" ]' _ "$FIX_MAIN" "$FIX_LANE"

assert "fixture: the linked worktree really is a linked worktree of the main checkout" \
    bash -c '[ "$(env -u GIT_DIR -u GIT_WORK_TREE -u GIT_COMMON_DIR -u GIT_INDEX_FILE \
        git -C "$2" rev-parse --path-format=absolute --git-common-dir)" = "$1/.git" ]' \
        _ "$FIX_MAIN" "$FIX_LANE"

# Precondition for the "outside any repo" case: $FIX_NOREPO must genuinely be
# outside every repository.  It normally is (TMPDIR is /tmp), but a TMPDIR
# nested inside a checkout would silently turn that case into a no-op, so the
# requirement is asserted rather than assumed.
assert "fixture: the non-repo scratch dir is genuinely outside any git repository" \
    bash -c '! env -u GIT_DIR -u GIT_WORK_TREE -u GIT_COMMON_DIR -u GIT_INDEX_FILE \
        git -C "$1" rev-parse --git-common-dir >/dev/null 2>&1' _ "$FIX_NOREPO"

echo ""
echo "--- A2: reify_main_checkout resolves the MAIN checkout from every anchor ---"

_R_MAIN="$(_resolver_out / "$FIX_MAIN")" || _R_MAIN=""
_R_MAIN_SUB="$(_resolver_out / "$FIX_MAIN/sub/deep")" || _R_MAIN_SUB=""
_R_LANE="$(_resolver_out / "$FIX_LANE")" || _R_LANE=""
_R_LANE_SUB="$(_resolver_out / "$FIX_LANE/sub/deep")" || _R_LANE_SUB=""

assert "A2a: anchored at the main checkout -> the main checkout root" \
    test "$_R_MAIN" = "$FIX_MAIN"

# Guards the --git-common-dir-is-RELATIVE-here trap: bare output is `.git` in
# the main checkout and `../../.git` from a subdir of it, so a resolver without
# --path-format=absolute answers `.` / `..` and is wrong precisely here.
assert "A2b: anchored at a SUBDIR of the main checkout -> the main checkout root" \
    test "$_R_MAIN_SUB" = "$FIX_MAIN"

assert "A2c: anchored at the LINKED WORKTREE -> the MAIN checkout root" \
    test "$_R_LANE" = "$FIX_MAIN"

assert "A2d: anchored at a SUBDIR of the linked worktree -> the MAIN checkout root" \
    test "$_R_LANE_SUB" = "$FIX_MAIN"

# THE BUG, stated directly: the whole defect is a host-global unit pinned at the
# linked worktree.  This is the assertion that would have caught it.
assert "A2e: the linked-worktree answer is NOT the linked worktree itself (the bug)" \
    bash -c '[ -n "$1" ] && [ "$1" != "$2" ]' _ "$_R_LANE" "$FIX_LANE"

echo ""
echo "--- A3: REIFY_MAIN_CHECKOUT override wins over the git derivation ---"

_R_OVERRIDE="$(_resolver_out / "$FIX_LANE" "REIFY_MAIN_CHECKOUT=$FIX_ROOT/override")" \
    || _R_OVERRIDE=""

assert "A3a: REIFY_MAIN_CHECKOUT set in the invocation env wins over git derivation" \
    test "$_R_OVERRIDE" = "$FIX_ROOT/override"

# ...and does not leak: the very next call, without it, must derive again.
assert "A3b: the override does not persist into a subsequent un-overridden call" \
    bash -c '[ "$1" = "$2" ]' _ "$(_resolver_out / "$FIX_LANE" || true)" "$FIX_MAIN"

echo ""
echo "--- A4: unresolvable anchors fail closed (non-zero, EMPTY stdout) ---"

_NOREPO_OUT=""; _NOREPO_RC=0
_NOREPO_OUT="$(_resolver_out / "$FIX_NOREPO" 2>/dev/null)" || _NOREPO_RC=$?

assert "A4a: anchored outside any git repo returns non-zero" \
    test "$_NOREPO_RC" -ne 0

# Never emit a guessed path: a bogus non-empty answer would be interpolated
# straight into an ExecStart and produce a silently dead unit.
assert "A4b: anchored outside any git repo prints NOTHING" \
    test -z "$_NOREPO_OUT"

_MISSING_OUT=""; _MISSING_RC=0
_MISSING_OUT="$(_resolver_out / "$FIX_ROOT/does-not-exist" 2>/dev/null)" || _MISSING_RC=$?

assert "A4c: anchored at a non-existent directory returns non-zero" \
    test "$_MISSING_RC" -ne 0

assert "A4d: anchored at a non-existent directory prints NOTHING" \
    test -z "$_MISSING_OUT"

echo ""
echo "--- A5: resolution does not depend on ambient CWD ---"

# `git rev-parse` resolves against CWD and setup-dev.sh has no top-level `cd`,
# so CWD is whatever the operator happened to be in.  Only a `git -C`-anchored
# resolver is deterministic.  Both answers must ALSO equal the main checkout,
# so two identical failures cannot pass this vacuously.
_R_CWD_SLASH="$(_resolver_out / "$FIX_LANE")" || _R_CWD_SLASH=""
_R_CWD_ROOT="$(_resolver_out "$FIX_ROOT" "$FIX_LANE")" || _R_CWD_ROOT=""

_CWD_INDEP=no
if [ -n "$_R_CWD_SLASH" ] && [ "$_R_CWD_SLASH" = "$_R_CWD_ROOT" ] && [ "$_R_CWD_SLASH" = "$FIX_MAIN" ]; then
    _CWD_INDEP=yes
fi

assert "A5a: same anchor from CWD=/ and CWD=<fixture root> -> same answer, == main checkout" \
    test "$_CWD_INDEP" = yes

echo ""
echo "--- A6: a hostile ambient git environment does not redirect the answer ---"

# GIT_DIR, GIT_WORK_TREE and GIT_COMMON_DIR all OUTRANK `git -C`, so without
# explicit neutralization inside the resolver, the `git -C "$anchor"` anchoring
# that A2/A5 pin is decorative: the answer comes from whatever repository the
# environment names.  This is not a contrived environment — git EXPORTS GIT_DIR
# into every hook, and reify runs its entire verify gate from
# hooks/pre-merge-commit, so this is the posture the resolver most often runs in.
#
# The poison target is $FIX_OTHER, an UNRELATED repo, precisely so the assertions
# below cannot pass vacuously: pointing the poison at the lane's own git dir
# would resolve back to $FIX_MAIN anyway and prove nothing.
_POISON_RAW=""
_POISON_RAW="$(GIT_DIR="$FIX_OTHER/.git" GIT_WORK_TREE="$FIX_OTHER" \
    git -C "$FIX_LANE" rev-parse --path-format=absolute --git-common-dir 2>/dev/null)" \
    || _POISON_RAW=""

# CONTROL, asserted FIRST: prove the poison actually works on a raw `git -C`.
# If a future git release stopped honouring these variables (or they were simply
# misspelled here), every assertion below would pass while testing nothing.
assert "A6a: CONTROL — poisoned env really does redirect a raw \`git -C\` to the other repo" \
    bash -c '[ -n "$1" ] && [ "$1" = "$2/.git" ] && [ "$2" != "$3" ]' \
        _ "$_POISON_RAW" "$FIX_OTHER" "$FIX_MAIN"

_R_POISON_DIR="$(_resolver_out / "$FIX_LANE" \
    "GIT_DIR=$FIX_OTHER/.git" "GIT_WORK_TREE=$FIX_OTHER")" || _R_POISON_DIR=""

assert "A6b: GIT_DIR+GIT_WORK_TREE exported, anchored at the lane -> still the MAIN checkout" \
    test "$_R_POISON_DIR" = "$FIX_MAIN"

# GIT_COMMON_DIR is the third override and the one most easily missed: it
# redirects --git-common-dir specifically, which is the exact query this
# resolver is built on.
_R_POISON_COMMON="$(_resolver_out / "$FIX_LANE" "GIT_COMMON_DIR=$FIX_OTHER/.git")" \
    || _R_POISON_COMMON=""

assert "A6c: GIT_COMMON_DIR exported, anchored at the lane -> still the MAIN checkout" \
    test "$_R_POISON_COMMON" = "$FIX_MAIN"

# The hook shape: setup-dev.sh (or a consumer) invoked from inside the MAIN
# checkout while git has exported a GIT_DIR for some other repository.
_R_POISON_MAIN="$(_resolver_out / "$FIX_MAIN" \
    "GIT_DIR=$FIX_OTHER/.git" "GIT_WORK_TREE=$FIX_OTHER")" || _R_POISON_MAIN=""

assert "A6d: GIT_DIR exported, anchored at the MAIN checkout -> still the MAIN checkout" \
    test "$_R_POISON_MAIN" = "$FIX_MAIN"

# =============================================================================
# PART B — the GENERATOR contract (setup-dev.sh install_build_services)
#
# Asserts on what the installer actually WRITES, in a sandboxed HOME. It does
# NOT inspect the real ~/.config/systemd/user: the live units were already
# hand-repointed by operator action on 2026-08-15, so any check against them
# would pass vacuously and prove nothing about the generator — which is the
# whole remaining value here. Nothing below runs systemctl (a restart of
# reify-jobserver.service re-seeds both FIFO pools and every in-flight verify
# rustc holding a token loses it permanently, fleet-wide), touches a host FIFO,
# or writes outside its mktemp root.
#
# CONTAINMENT IS BY CONSTRUCTION, not by assertion: _run_generator overrides
# HOME to the fixture's, and $unit_dir is derived from $HOME inside
# install_build_services(), so the real ~/.config/systemd/user is unreachable
# from here. There is deliberately no assertion for it — an assertion could only
# re-measure the override it already depends on.
# =============================================================================
echo ""
echo "--- B0: generator fixture (function extracted into a FAKE LANE) ---"

# ---------------------------------------------------------------------------
# _mk_generator_fixture <stem> [MODE] — MAIN-SHELL ONLY (see
# _mk_two_checkout_fixture for why this sets globals rather than echoing them).
# Sets GEN_ROOT/GEN_MAIN/GEN_LANE/GEN_HOME/GEN_UNITS/GEN_SYSTEMCTL_LOG.
#
# MODE selects which branch of the installer's pin decision the fixture drives:
#   main-exec    (default) the main checkout resolves AND holds both executables
#                -> the PIN is taken, units name the main checkout. B1-B4.
#   main-noexec  the main checkout resolves but its two scripts are NOT
#                executable -> the FALLBACK is taken, units name the invoking
#                lane and the installer warns. B6.
#   lane-norepo  the invoking tree is not a git worktree at all, so the resolver
#                fails outright -> the FALLBACK is taken with an EMPTY
#                main_checkout, exercising the `<unresolved>` message. B7.
#   main-only    the invoking tree IS the main checkout, and its scripts are not
#                executable -> main_checkout == repo_dir, the case an
#                `!= "$repo_dir"`-gated warn would swallow. B8.
#   fallback-noscripts
#                the fallback is taken at a tree that does not hold the scripts
#                at all, so the trailing `chmod +x` fails -> exercises the
#                non-fatal chmod guard. B9.
#
# The fallback branch matters disproportionately: it is the one whose guard,
# if it were ever inverted or dropped, silently re-creates the original 203/EXEC
# defect. Covering only main-exec would leave it green under exactly that edit.
#
# The executable stubs and a copy of lib_main_checkout.sh are COMMITTED before
# `git worktree add`, so the linked worktree carries them too — the installer
# must be able to find its executables in whichever tree it ends up pinning,
# or a passing test could not distinguish "pinned correctly" from "chmod
# happened to fail".
#
# install_build_services() is extracted by column-0 sed anchors and written to
# <fake lane>/scripts/setup-dev.sh, so ${BASH_SOURCE[0]} inside the function
# resolves to the FAKE LANE. That is what reproduces the bug's exact trigger
# condition — an installer invoked from a warm lane — rather than simulating
# it. setup-dev.sh cannot simply be sourced: it is straight-line and would
# apt-install, curl rustup and build native deps long before reaching the
# function.
# ---------------------------------------------------------------------------
_mk_generator_fixture() {
    local stem="$1" mode="${2:-main-exec}" root
    _mk_fixture_root "$stem" || return 1
    root="$_FIXTURE_ROOT"
    GEN_ROOT="$root"
    GEN_MAIN="$root/main"
    GEN_LANE="$root/lane"
    GEN_HOME="$root/home"
    GEN_UNITS="$GEN_HOME/.config/systemd/user"

    mkdir -p "$GEN_MAIN/scripts" "$GEN_HOME/.cargo/bin" "$root/shim" || return 1

    # The recording `systemctl` (see _write_systemctl_shim). B9c is the case
    # that needs the recording rather than a bare no-op.
    GEN_SYSTEMCTL_LOG="$root/systemctl.log"
    _write_systemctl_shim "$root/shim" "$GEN_SYSTEMCTL_LOG" || return 1

    # The two executables the jobserver units name in their ExecStart, plus the
    # resolver the installer sources.
    printf '#!/usr/bin/env bash\nexit 0\n' > "$GEN_MAIN/scripts/jobserver-balancer.py" || return 1
    printf '#!/usr/bin/env bash\nexit 0\n' > "$GEN_MAIN/scripts/jobserver-canary.sh" || return 1
    cp "$REPO_ROOT/scripts/lib_main_checkout.sh" "$GEN_MAIN/scripts/lib_main_checkout.sh" || return 1
    chmod +x "$GEN_MAIN/scripts/jobserver-balancer.py" "$GEN_MAIN/scripts/jobserver-canary.sh" || return 1

    _fixture_init_commit "$GEN_MAIN" || return 1

    if [ "$mode" = main-only ]; then
        # No linked worktree at all: the invoking tree IS the main checkout, so
        # repo_dir and main_checkout resolve to the same path.
        GEN_LANE="$GEN_MAIN"
    elif [ "$mode" = lane-norepo ]; then
        # A plain directory, NOT a worktree: `git worktree add` is skipped
        # entirely so reify_main_checkout() fails outright from this anchor.
        # It still carries the scripts and the resolver, so the ONLY thing being
        # exercised is the unresolvable-anchor branch.
        mkdir -p "$GEN_LANE/scripts" || return 1
        cp "$GEN_MAIN/scripts/jobserver-balancer.py" \
           "$GEN_MAIN/scripts/jobserver-canary.sh" \
           "$GEN_MAIN/scripts/lib_main_checkout.sh" "$GEN_LANE/scripts/" || return 1
    else
        _fixture_git -C "$GEN_MAIN" worktree add -q --detach "$GEN_LANE" >/dev/null 2>&1 || return 1
        mkdir -p "$GEN_LANE/scripts" || return 1
    fi

    if [ "$mode" = main-noexec ] || [ "$mode" = main-only ] \
        || [ "$mode" = fallback-noscripts ]; then
        # Strip the exec bit in the MAIN checkout ONLY, and only AFTER the
        # worktree add: the lane's copies are separate inodes checked out at the
        # committed mode 755, so they stay runnable. That asymmetry is exactly
        # the shape the fallback exists for — the main checkout resolves, but
        # cannot run what the units would name.
        chmod -x "$GEN_MAIN/scripts/jobserver-balancer.py" \
                 "$GEN_MAIN/scripts/jobserver-canary.sh" || return 1
    fi

    if [ "$mode" = fallback-noscripts ]; then
        # ...and the tree the fallback lands on does not hold them AT ALL, so
        # the installer's trailing `chmod +x` fails with ENOENT. A portable
        # stand-in for the real-world failures (EPERM on a main checkout owned
        # by another uid, EROFS on a read-only mount) that a hermetic test
        # cannot manufacture.
        rm -f "$GEN_LANE/scripts/jobserver-balancer.py" \
              "$GEN_LANE/scripts/jobserver-canary.sh" || return 1
    fi

    sed -n '/^install_build_services() {$/,/^}$/p' "$REPO_ROOT/scripts/setup-dev.sh" \
        > "$GEN_LANE/scripts/setup-dev.sh" || return 1
    return 0
}

# ---------------------------------------------------------------------------
# _run_generator — source the extracted function in a sandboxed environment and
# invoke it. HOME is the fixture's, PATH is shimmed, and the log helpers
# setup-dev.sh defines at top level (which the extraction deliberately does not
# carry) are stubbed. warn/err are echoed to stderr so a fallback taken during
# the run is visible in the captured-output dump of a failing assert.
# ---------------------------------------------------------------------------
_run_generator() {
    env -u REIFY_MAIN_CHECKOUT -u REIFY_SCCACHE_SIZE \
        HOME="$GEN_HOME" PATH="$GEN_ROOT/shim:$PATH" \
        bash -c '
            set -euo pipefail
            info() { :; }
            ok()   { :; }
            warn() { echo "warn: $*" >&2; }
            err()  { echo "err: $*" >&2; }
            source "$1"
            install_build_services
        ' _ "$GEN_LANE/scripts/setup-dev.sh"
}

# ---------------------------------------------------------------------------
# _exec_lines <unit_dir> — every `Exec*=` line across every emitted *.service,
# as "<unit basename>|<argv0>".
#
# argv[0] ONLY — the first whitespace-separated token, with systemd's `-@+!:`
# run-time prefix characters stripped. A worktree path passed as a DATA
# ARGUMENT is legitimate (deploy/systemd/reify-warm-lane-gc.service correctly
# carries `--mount /home/leo/src/warm-lanes/worktrees`), so a naive grep for
# the lane path over whole unit files would over-match and make this guard
# untrustworthy. Only the EXECUTABLE is the defect.
# ---------------------------------------------------------------------------
_exec_lines() {
    local unit_dir="$1" f line val
    for f in "$unit_dir"/*.service; do
        [ -f "$f" ] || continue
        while IFS= read -r line || [ -n "$line" ]; do
            case "$line" in
                Exec*=*) ;;
                *) continue ;;
            esac
            val="${line#*=}"
            while [ -n "$val" ]; do
                case "$val" in
                    [-@+!:]*) val="${val#?}" ;;
                    *) break ;;
                esac
            done
            printf '%s|%s\n' "${f##*/}" "${val%%[[:space:]]*}"
        done < "$f"
    done
}

