# =============================================================================
# Part C — the BOOT-UNIT generator contract
#   scripts/setup-agent-cache-redirect.sh's install_boot_unit()  (task 6864)
#
# The SECOND host-global unit generator on this host, and until task 6864 the
# one that still resolved the main checkout PRIVATELY, as
# `${REIFY_MAIN_CHECKOUT:-/home/leo/src/reify}` — a hardcoded host default where
# Part B's generator DERIVES the answer from git. The two agreed on the reify
# host and on any host exporting REIFY_MAIN_CHECKOUT, and disagreed SILENTLY on
# a contributor clone or a relocated tree: the redirect script pinned its boot
# unit at a nonexistent /home/leo/src/reify and fell back to $self. This Part
# mirrors Part B one-for-one for that generator.
#
# WHY THIS COVERAGE LIVES HERE AND NOT IN tests/infra/test_agent_cache_redirect.sh:
# every behavioural case in that suite's Block H pins REIFY_MAIN_CHECKOUT
# explicitly — its run_redirect helper hardcodes it so no run can reach the real
# host default, and H8/H11b override it again — and layer 1 of
# reify_main_checkout honours that override verbatim. So no run THERE can
# observe which resolver produced the answer; that suite's behavioural
# assertions are regression coverage, not discrimination. Only a run with REIFY_MAIN_CHECKOUT
# UNSET, inside a real linked worktree, discriminates. That is this Part —
# which makes C1c, not any grep, the assertion a silent revert of the migration
# has to get past. Block H keeps the regression matrix plus one cheap local
# canary (H8d, with H8f as its non-vacuity).
#
# The BU_* globals are deliberately NOT the GEN_* ones Part B uses. Part B's
# sections rebind those in place, and a shared name would suggest the two Parts
# drove the same fixture generator.
# =============================================================================

# ---------------------------------------------------------------------------
# _mk_boot_unit_fixture <stem> [MODE] — MAIN-SHELL ONLY (see
# _mk_two_checkout_fixture for why this sets globals rather than echoing them).
# Sets BU_ROOT/BU_MAIN/BU_LANE/BU_HOME/BU_UNITS/BU_UNIT/BU_SYSTEMCTL_LOG.
#
# MODE selects which branch of install_boot_unit()'s pin decision it drives:
#   lane         (default) a real linked worktree, and the main checkout holds
#                an EXECUTABLE copy of the script -> the PIN is taken, the unit
#                names the main checkout. C1-C4.
#   main-noexec  the main checkout resolves but its copy is NOT executable ->
#                the FALLBACK is taken and the installer warns. C5.
#   lane-norepo  the invoking tree is not a git worktree at all, so
#                reify_main_checkout() fails outright -> fail-open with an EMPTY
#                main_checkout. C6.
#   nolib        the resolver is absent from the invoking tree entirely, so the
#                `-r` source guard is what has to hold. C7.
#   nofunc       the resolver is PRESENT, readable, and sources cleanly — it
#                just defines nothing, because its own source guard is already
#                satisfied. `-r` passes and the `.` succeeds, so the resolution
#                has to come back EMPTY without taking the function down with
#                it. The state C7 structurally cannot reach. C9.
#
# The fallback branches matter disproportionately: they are the ones whose
# guards, if inverted or dropped, silently re-create the original 203/EXEC
# defect — and the script runs under `set -euo pipefail`, so a resolver that
# returns non-zero unguarded would abort a deliberately fail-open provisioning
# step instead.
#
# The script and the resolver are COMMITTED mode 755 BEFORE `git worktree add`,
# so the linked lane checks out its own separate, executable inodes. That
# asymmetry is what lets main-noexec strip the exec bit from the main copy alone.
#
# install_boot_unit() is extracted by column-0 sed anchors and written to
# <fake lane>/scripts/setup-agent-cache-redirect.sh, so ${BASH_SOURCE[0]} inside
# the function resolves to the FAKE LANE — REPRODUCING the invoked-from-a-warm-
# lane trigger rather than simulating it. The full script cannot simply be
# sourced: it is straight-line and would run the whole hardlink pre-seed and the
# sudo'd tmpfiles install long before reaching the function.
# ---------------------------------------------------------------------------
_mk_boot_unit_fixture() {
    local stem="$1" mode="${2:-lane}" root
    _mk_fixture_root "$stem" || return 1
    root="$_FIXTURE_ROOT"
    BU_ROOT="$root"
    BU_MAIN="$root/main"
    BU_LANE="$root/lane"
    BU_HOME="$root/home"
    BU_UNITS="$BU_HOME/.config/systemd/user"
    BU_UNIT="$BU_UNITS/reify-agent-caches.service"

    mkdir -p "$BU_MAIN/scripts" "$BU_HOME/.config" "$root/shim" || return 1

    # The recording `systemctl` (see _write_systemctl_shim). This function also
    # PROBES the --user bus with `show-environment` before doing anything, so
    # the shim is what keeps the whole Part from short-circuiting into the
    # no-bus skip on a CI box. C4 is the case that needs the recording.
    BU_SYSTEMCTL_LOG="$root/systemctl.log"
    _write_systemctl_shim "$root/shim" "$BU_SYSTEMCTL_LOG" || return 1

    # The MAIN checkout holds the executable copy the unit's ExecStart must
    # name, plus the resolver the function sources.
    cp "$REPO_ROOT/scripts/setup-agent-cache-redirect.sh" "$BU_MAIN/scripts/" || return 1
    cp "$REPO_ROOT/scripts/lib_main_checkout.sh" "$BU_MAIN/scripts/" || return 1
    chmod +x "$BU_MAIN/scripts/setup-agent-cache-redirect.sh" || return 1

    _fixture_init_commit "$BU_MAIN" || return 1

    if [ "$mode" = lane-norepo ]; then
        # A plain directory, NOT a worktree: `git worktree add` is skipped
        # entirely so reify_main_checkout() fails outright from this anchor. It
        # still carries the resolver, so the ONLY thing exercised is the
        # unresolvable-anchor branch.
        mkdir -p "$BU_LANE/scripts" || return 1
        cp "$BU_MAIN/scripts/lib_main_checkout.sh" "$BU_LANE/scripts/" || return 1
    else
        _fixture_git -C "$BU_MAIN" worktree add -q --detach "$BU_LANE" >/dev/null 2>&1 || return 1
    fi

    if [ "$mode" = main-noexec ]; then
        # Strip the exec bit in the MAIN checkout ONLY, and only AFTER the
        # worktree add: the lane's copy is a separate inode checked out at the
        # committed mode 755, so it stays runnable. That asymmetry is exactly
        # the shape the fallback exists for — the main checkout resolves, but
        # holds nothing the unit could execute.
        chmod -x "$BU_MAIN/scripts/setup-agent-cache-redirect.sh" || return 1
    fi

    if [ "$mode" = nolib ]; then
        rm -f "$BU_LANE/scripts/lib_main_checkout.sh" || return 1
    fi

    if [ "$mode" = nofunc ]; then
        # REPRODUCED, not simulated: this IS the real lib, with its own source-
        # guard variable pre-set on the line above it. Sourcing it therefore
        # takes the `return 0` at lib_main_checkout.sh's guard and defines
        # NOTHING — precisely what an exported
        # _REIFY_LIB_MAIN_CHECKOUT_SH_SOURCED=1 in the ambient environment does
        # in production, and what a half-written or renamed-function lib does by
        # accident. Unlike nolib, `-r` passes and the `.` succeeds here, so the
        # fail-open outcome has to come from the CALL SITE rather than from the
        # source guard. See C9's banner for what that does and does not pin.
        {
            printf '%s\n' '_REIFY_LIB_MAIN_CHECKOUT_SH_SOURCED=1'
            cat "$BU_MAIN/scripts/lib_main_checkout.sh"
        } > "$BU_LANE/scripts/lib_main_checkout.sh" || return 1
    fi

    mkdir -p "$BU_LANE/scripts" || return 1
    sed -n '/^install_boot_unit() {$/,/^}$/p' \
        "$REPO_ROOT/scripts/setup-agent-cache-redirect.sh" \
        > "$BU_LANE/scripts/setup-agent-cache-redirect.sh" || return 1
    chmod +x "$BU_LANE/scripts/setup-agent-cache-redirect.sh" || return 1
    return 0
}

# ---------------------------------------------------------------------------
# _run_boot_unit — source the extracted function in a sandboxed environment and
# invoke it. HOME and XDG_CONFIG_HOME are the fixture's, PATH is shimmed, and
# the log helpers the script defines at top level (which the extraction
# deliberately does not carry) are stubbed. _warn is echoed to stderr so a
# fallback taken during the run is visible in a failing assert's dump.
#
# `env -u REIFY_MAIN_CHECKOUT` is THE point of this Part: with the override set,
# layer 1 of reify_main_checkout short-circuits the git derivation and the run
# would certify nothing about which resolver is in use. The ambient GIT_* are
# deliberately NOT stripped — the resolver has to neutralize those itself (Part
# A's A6), and a harness that pre-cleaned them would be certifying a posture
# production never has.
# ---------------------------------------------------------------------------
_run_boot_unit() {
    env -u REIFY_MAIN_CHECKOUT \
        HOME="$BU_HOME" \
        XDG_CONFIG_HOME="$BU_HOME/.config" \
        PATH="$BU_ROOT/shim:$PATH" \
        bash -c '
            set -euo pipefail
            _info() { :; }
            _ok()   { :; }
            _warn() { echo "warn: $*" >&2; }
            source "$1"
            install_boot_unit
        ' _ "$BU_LANE/scripts/setup-agent-cache-redirect.sh"
}

# ---------------------------------------------------------------------------
# _no_root_relative_path <file> — 0 when <file> mentions no ROOT-RELATIVE
# `/scripts/setup-agent-cache-redirect.sh`, i.e. the string an EMPTY
# $main_checkout interpolates into.
#
# The literal is a SUFFIX of every legitimate absolute path too, so a plain
# `grep -F` would match always and certify nothing. The match is therefore
# anchored on what PRECEDES it: a legitimate path has a directory-name character
# there, the unresolved one has a delimiter (line start, whitespace, `(`, `=`).
# ---------------------------------------------------------------------------
_no_root_relative_path() {
    ! grep -qE '(^|[^[:alnum:]_.~-])/scripts/setup-agent-cache-redirect\.sh' "$1"
}

echo ""
echo "--- C0: boot-unit fixture (function extracted into a FAKE LANE) ---"

BU_ROOT=""; BU_MAIN=""; BU_LANE=""; BU_HOME=""; BU_UNITS=""; BU_UNIT=""; BU_SYSTEMCTL_LOG=""
_mk_boot_unit_fixture reify-bootfix   # main shell, NOT $( )

_BU_EXTRACT="$BU_LANE/scripts/setup-agent-cache-redirect.sh"

assert "C0a: the extracted snippet is non-empty" \
    test -s "$_BU_EXTRACT"

assert "C0b: the extracted snippet defines install_boot_unit" \
    grep -qF 'install_boot_unit() {' "$_BU_EXTRACT"

assert "C0c: the extracted snippet carries the --seed-only ExecStart" \
    bash -c 'grep -qE "^ExecStart=.* --seed-only$" "$1"' _ "$_BU_EXTRACT"

# The bug's trigger condition: the installer is running from a DIFFERENT tree
# than the one its host-global unit must name.
assert "C0d: the fake lane and the main checkout are DISTINCT paths" \
    bash -c '[ "$1" != "$2" ]' _ "$BU_LANE" "$BU_MAIN"

# NON-VACUITY for C1/C2: if the main copy were not executable the -x guard would
# send us down the fallback and C1 would be measuring some other branch; if the
# lane copy were not, C2 could pass for the wrong reason.
assert "C0e: BOTH the main and the lane copies are executable" \
    bash -c '[ -x "$1/scripts/setup-agent-cache-redirect.sh" ] \
             && [ -x "$2/scripts/setup-agent-cache-redirect.sh" ]' \
        _ "$BU_MAIN" "$BU_LANE"

echo ""
echo "--- C1-C4: derivation from a linked lane pins the MAIN checkout ---"

_BU_RC=0
_BU_ERR="$BU_ROOT/boot.err"
_run_boot_unit >"$BU_ROOT/boot.out" 2>"$_BU_ERR" || _BU_RC=$?

assert "C1a: install_boot_unit() completes successfully in the sandbox" \
    bash -c '[ "$1" = "0" ] || { cat "$2" >&2; exit 1; }' _ "$_BU_RC" "$_BU_ERR"

assert "C1b: it wrote reify-agent-caches.service into the sandboxed unit dir" \
    test -f "$BU_UNIT"

assert "C1c: ExecStart == <main checkout>/scripts/setup-agent-cache-redirect.sh --seed-only" \
    bash -c '[ "$(grep "^ExecStart=" "$1" | head -1)" \
              = "ExecStart=$2/scripts/setup-agent-cache-redirect.sh --seed-only" ]' \
        _ "$BU_UNIT" "$BU_MAIN"

# What gives C5f/C6d/C7d teeth in the other direction. Those three assert the
# fallback warn is PRESENT; without this, a regression that warned
# UNCONDITIONALLY — the `[ -n "$stable" ] && [ -x "$stable" ]` short-circuit
# dropped, or the warn hoisted above the branch — would leave every one of them
# green AND leave C1c/C2/C3 green, because the ExecStart would still be right.
# The suite would then be unable to tell "pinned cleanly" from "pinned correctly
# while shouting a spurious fallback warning at every operator", which is what
# trains operators to ignore the one warn that matters.
assert "C1d: the success path emits NO fallback warn" \
    bash -c '! grep -qF "pinning the boot unit at the invoking copy" "$1"' _ "$_BU_ERR"

# The half that gives C1c teeth: the lane path is what a ${BASH_SOURCE[0]}-derived
# ExecStart would have baked in, and it vanishes the next time that lane is
# reclaimed.
assert "C2: ExecStart is NOT the invoking (warm-lane) copy" \
    bash -c '! grep -qF -- "ExecStart=$2/scripts/setup-agent-cache-redirect.sh" "$1"' \
        _ "$BU_UNIT" "$BU_LANE"

assert "C3: Documentation=file:// also names the MAIN copy, not the lane copy" \
    bash -c 'grep -qF -- "Documentation=file://$2/scripts/setup-agent-cache-redirect.sh" "$1"' \
        _ "$BU_UNIT" "$BU_MAIN"

assert "C4a: systemctl --user daemon-reload was called" \
    bash -c 'grep -qF -- "--user daemon-reload" "$1"' _ "$BU_SYSTEMCTL_LOG"

assert "C4b: systemctl --user enable naming reify-agent-caches.service was called" \
    bash -c 'grep -qE -- "--user enable.*reify-agent-caches\.service" "$1"' _ "$BU_SYSTEMCTL_LOG"

assert "C4c: daemon-reload precedes enable in call order" \
    bash -c '
        r=$(grep -n "daemon-reload" "$1" | head -1 | cut -d: -f1)
        e=$(grep -n "enable.*reify-agent-caches.service" "$1" | head -1 | cut -d: -f1)
        [ -n "$r" ] && [ -n "$e" ] && [ "$r" -lt "$e" ]
    ' _ "$BU_SYSTEMCTL_LOG"

echo ""
echo "--- C5: FALLBACK — the main checkout resolves but holds no executable ---"

# The branch whose guard, if inverted or dropped, silently re-creates the
# original 203/EXEC defect. Each section below RE-BINDS the BU_* globals to a
# fresh fixture, so nothing after a section may read the previous one's.
_mk_boot_unit_fixture reify-bootfix-noexec main-noexec   # main shell, NOT $( )

assert "C5a: NON-VACUITY — the MAIN copy is NOT executable" \
    bash -c '[ ! -x "$1/scripts/setup-agent-cache-redirect.sh" ]' _ "$BU_MAIN"

assert "C5b: NON-VACUITY — the invoking lane copy IS still executable" \
    bash -c '[ -x "$1/scripts/setup-agent-cache-redirect.sh" ]' _ "$BU_LANE"

_BU2_RC=0
_BU2_ERR="$BU_ROOT/boot.err"
_BU2_UNIT="$BU_UNIT"
_run_boot_unit >"$BU_ROOT/boot.out" 2>"$_BU2_ERR" || _BU2_RC=$?

assert "C5c: install_boot_unit() still completes on the fallback path" \
    bash -c '[ "$1" = "0" ] || { cat "$2" >&2; exit 1; }' _ "$_BU2_RC" "$_BU2_ERR"

assert "C5d: the unit is STILL installed" \
    test -f "$_BU2_UNIT"

assert "C5e: ExecStart falls back to the INVOKING lane copy" \
    bash -c '[ "$(grep "^ExecStart=" "$1" | head -1)" \
              = "ExecStart=$2/scripts/setup-agent-cache-redirect.sh --seed-only" ]' \
        _ "$_BU2_UNIT" "$BU_LANE"

# A silent fallback is the failure mode the whole convention exists to prevent:
# pinning at an ephemeral lane is survivable when it is ANNOUNCED.
assert "C5f: the installer WARNS that it pinned at the invoking copy" \
    grep -qF 'pinning the boot unit at the invoking copy' "$_BU2_ERR"

assert "C5g: the warn names the resolved main checkout it rejected" \
    bash -c 'grep -qF -- "$2" "$1"' _ "$_BU2_ERR" "$BU_MAIN"

# The remedy clause is branch-specific, and this is the branch it must NOT
# appear on: the derivation SUCCEEDED here, so telling the operator to set
# REIFY_MAIN_CHECKOUT would point them at a knob that changes nothing. C6e is
# the positive half.
assert "C5h: the warn does NOT offer the REIFY_MAIN_CHECKOUT remedy (it resolved)" \
    bash -c '! grep -qF "set REIFY_MAIN_CHECKOUT" "$1"' _ "$_BU2_ERR"

echo ""
echo "--- C6: FAIL-OPEN — the resolver fails outright (anchor is not a worktree) ---"

_mk_boot_unit_fixture reify-bootfix-norepo lane-norepo   # main shell, NOT $( )

assert "C6a: NON-VACUITY — the invoking tree is genuinely outside any git worktree" \
    bash -c '! env -u GIT_DIR -u GIT_WORK_TREE -u GIT_COMMON_DIR -u GIT_INDEX_FILE \
        git -C "$1" rev-parse --git-common-dir >/dev/null 2>&1' _ "$BU_LANE"

_BU3_RC=0
_BU3_ERR="$BU_ROOT/boot.err"
_BU3_UNIT="$BU_UNIT"
_run_boot_unit >"$BU_ROOT/boot.out" 2>"$_BU3_ERR" || _BU3_RC=$?

# `set -euo pipefail` is live in the extracted function's shell, and
# reify_main_checkout returns NON-ZERO when it cannot resolve. An unguarded call
# would abort here rather than degrade — which is why the rc assertion is the
# first thing this section checks.
assert "C6b: install_boot_unit() still exits 0 with an unresolvable main checkout" \
    bash -c '[ "$1" = "0" ] || { cat "$2" >&2; exit 1; }' _ "$_BU3_RC" "$_BU3_ERR"

assert "C6c: the unit is STILL installed, pinned at the invoking lane copy" \
    bash -c '[ "$(grep "^ExecStart=" "$1" | head -1)" \
              = "ExecStart=$2/scripts/setup-agent-cache-redirect.sh --seed-only" ]' \
        _ "$_BU3_UNIT" "$BU_LANE"

assert "C6d: the installer WARNS that it pinned at the invoking copy" \
    grep -qF 'pinning the boot unit at the invoking copy' "$_BU3_ERR"

# `<unresolved>` says what failed but not what to do about it, and the unit the
# operator is left with is the ephemeral one — the 203/EXEC shape. On this
# branch the warn must therefore name the override that pins it at a stable
# path; C5h is the negative half, on the branch where it would be wrong advice.
assert "C6e: the warn names the REIFY_MAIN_CHECKOUT remedy" \
    grep -qF 'set REIFY_MAIN_CHECKOUT' "$_BU3_ERR"

echo ""
echo "--- C7: FAIL-OPEN — the resolver is not present in the invoking tree ---"

# Proves the `-r` SOURCE GUARD is load-bearing rather than decorative: with the
# file absent, the function must still produce a working unit. It says nothing
# about what happens when the lib is present but defines nothing — `-r`
# short-circuits before anything downstream is reached — which is why C9 exists
# as a separate case rather than as more assertions here.
_mk_boot_unit_fixture reify-bootfix-nolib nolib   # main shell, NOT $( )

assert "C7a: NON-VACUITY — the invoking tree holds no lib_main_checkout.sh" \
    bash -c '[ ! -e "$1/scripts/lib_main_checkout.sh" ]' _ "$BU_LANE"

_BU4_RC=0
_BU4_ERR="$BU_ROOT/boot.err"
_BU4_UNIT="$BU_UNIT"
_run_boot_unit >"$BU_ROOT/boot.out" 2>"$_BU4_ERR" || _BU4_RC=$?

assert "C7b: install_boot_unit() still exits 0 with no resolver available" \
    bash -c '[ "$1" = "0" ] || { cat "$2" >&2; exit 1; }' _ "$_BU4_RC" "$_BU4_ERR"

assert "C7c: the unit is STILL installed, pinned at the invoking lane copy" \
    bash -c '[ "$(grep "^ExecStart=" "$1" | head -1)" \
              = "ExecStart=$2/scripts/setup-agent-cache-redirect.sh --seed-only" ]' \
        _ "$_BU4_UNIT" "$BU_LANE"

assert "C7d: the installer WARNS that it pinned at the invoking copy" \
    grep -qF 'pinning the boot unit at the invoking copy' "$_BU4_ERR"

echo ""
echo "--- C8: an UNRESOLVED main checkout is never rendered as a bare leading / ---"

# The counterpart of Part B's B7d. An empty $main_checkout must not be
# interpolated into a path at all: neither into the unit (which the -x guard
# already prevents) nor into the operator-facing warn, where
# `/scripts/setup-agent-cache-redirect.sh` names a file that exists nowhere and
# tells the reader nothing about what actually failed.
assert "C8a: (lane-norepo) the emitted unit carries no root-relative path" \
    _no_root_relative_path "$_BU3_UNIT"

assert "C8b: (lane-norepo) the warn carries no root-relative path" \
    _no_root_relative_path "$_BU3_ERR"

assert "C8c: (nolib) the emitted unit carries no root-relative path" \
    _no_root_relative_path "$_BU4_UNIT"

assert "C8d: (nolib) the warn carries no root-relative path" \
    _no_root_relative_path "$_BU4_ERR"

echo ""
echo "--- C9: FAIL-OPEN — the resolver sources cleanly but defines nothing ---"

# The present-but-defines-nothing state, which C7 structurally CANNOT reach:
# there the file is absent, so the `-r` guard short-circuits and nothing
# downstream of it is exercised at all. Here `-r` passes and the `.` succeeds,
# and the resolution still has to come back empty without taking the function
# down with it.
#
# Not a contrived state: _REIFY_LIB_MAIN_CHECKOUT_SH_SOURCED is a plain shell
# variable, so an exported value in the ambient environment makes the REAL,
# unmodified lib take its source-guard `return 0` before defining anything —
# which is exactly what this fixture reproduces. A half-written lib, or one
# whose function was renamed, lands in the same state by accident.
#
# WHAT THIS PINS IS THE OUTCOME, NOT WHICH GUARD PRODUCES IT — deliberately, and
# on measurement rather than taste. Deleting install_boot_unit()'s `declare -F`
# guard leaves this entire Part green, because
# `$(reify_main_checkout ... 2>/dev/null || true)` already absorbs the
# command-not-found (exit 127) into an empty string without tripping
# `set -euo pipefail` — probed directly, both by that mutation and standalone.
# The two call-site guards are therefore REDUNDANT here rather than layered, and
# an assertion naming `declare -F` as the load-bearing one would be pinning
# something false. What must hold — and what C9c-C9f pin — is that this state
# degrades fail-open at all, whichever guard gets there first.
_mk_boot_unit_fixture reify-bootfix-nofunc nofunc   # main shell, NOT $( )

assert "C9a: NON-VACUITY — the lib IS present and readable in the invoking tree" \
    bash -c '[ -r "$1/scripts/lib_main_checkout.sh" ]' _ "$BU_LANE"

assert "C9b: NON-VACUITY — sourcing it defines no reify_main_checkout" \
    bash -c '. "$1" >/dev/null 2>&1; ! declare -F reify_main_checkout >/dev/null 2>&1' \
        _ "$BU_LANE/scripts/lib_main_checkout.sh"

_BU5_RC=0
_BU5_ERR="$BU_ROOT/boot.err"
_BU5_UNIT="$BU_UNIT"
_run_boot_unit >"$BU_ROOT/boot.out" 2>"$_BU5_ERR" || _BU5_RC=$?

assert "C9c: install_boot_unit() still exits 0 when the lib defines nothing" \
    bash -c '[ "$1" = "0" ] || { cat "$2" >&2; exit 1; }' _ "$_BU5_RC" "$_BU5_ERR"

assert "C9d: the unit is STILL installed, pinned at the invoking lane copy" \
    bash -c '[ "$(grep "^ExecStart=" "$1" | head -1)" \
              = "ExecStart=$2/scripts/setup-agent-cache-redirect.sh --seed-only" ]' \
        _ "$_BU5_UNIT" "$BU_LANE"

assert "C9e: the installer WARNS that it pinned at the invoking copy" \
    grep -qF 'pinning the boot unit at the invoking copy' "$_BU5_ERR"

assert "C9f: the warn carries no root-relative path" \
    _no_root_relative_path "$_BU5_ERR"

# -- Summary ------------------------------------------------------------------
test_summary
